import type { Condition } from '../conditions/types.ts';
import type { LocalizedText } from '../i18n.ts';

/** Properties every field has, whatever its type (custom ones included). */
export interface FieldBase {
	/** Stable ID (generated by the builder). Answers and conditions use it. */
	readonly id: string;
	/** Name used in exports. Default: the `id`. */
	readonly key?: string;
	readonly type: string;
	readonly label: LocalizedText;
	readonly description?: LocalizedText;
	readonly required?: boolean;
	/** The field only shows up (and is only validated) when the condition is true. */
	readonly showIf?: Condition;
}

export interface ChoiceOption {
	/** Stable ID: this goes into the answer, not the label. */
	readonly id: string;
	readonly label: LocalizedText;
}

export interface TextField extends FieldBase {
	readonly type: 'text';
	readonly minLength?: number;
	readonly maxLength?: number;
	readonly format?: 'email' | 'url';
	readonly placeholder?: LocalizedText;
}

export interface LongTextField extends FieldBase {
	readonly type: 'longText';
	readonly minLength?: number;
	readonly maxLength?: number;
	readonly placeholder?: LocalizedText;
}

export interface NumberField extends FieldBase {
	readonly type: 'number';
	readonly min?: number;
	readonly max?: number;
	readonly integer?: boolean;
	readonly placeholder?: LocalizedText;
}

export interface BooleanField extends FieldBase {
	readonly type: 'boolean';
}

export interface ChoiceField extends FieldBase {
	readonly type: 'choice';
	readonly options: readonly ChoiceOption[];
}

export interface MultiChoiceField extends FieldBase {
	readonly type: 'multiChoice';
	readonly options: readonly ChoiceOption[];
	readonly minSelected?: number;
	readonly maxSelected?: number;
}

export interface ScaleField extends FieldBase {
	readonly type: 'scale';
	/** Default: 1. */
	readonly min?: number;
	/** Default: 5. */
	readonly max?: number;
	readonly minLabel?: LocalizedText;
	readonly maxLabel?: LocalizedText;
}

/** Informational block (title/text). Has no answer. */
export interface SectionField extends FieldBase {
	readonly type: 'section';
}

export type BuiltinField =
	| TextField
	| LongTextField
	| NumberField
	| BooleanField
	| ChoiceField
	| MultiChoiceField
	| ScaleField
	| SectionField;

export type BuiltinFieldType = BuiltinField['type'];

export interface FormSchema<F extends FieldBase = FieldBase> {
	readonly id: string;
	/** Integer >= 1. Bump it when the form changes; answers store the version. */
	readonly version: number;
	readonly title?: LocalizedText;
	readonly description?: LocalizedText;
	readonly fields: readonly F[];
}
